<script setup>
const {user,send,busy,fa}=useReiki()
const {data:programs,error,refresh}=await useFetch('/api/catalog/programs')
const selected=ref(null),day=ref(null)
async function done(p,d){if(!user.value)return navigateTo('/profile');if(await send('/api/account/programs',{id:p.id,day:d.day_number}))await refresh()}
</script>
<template><main class="page"><div class="page-heading"><small>آرام، پیوسته، برای خودت</small><h1>مسیر تمرین</h1></div><p v-if="error">دریافت برنامه‌ها ممکن نشد.</p><div class="stack"><article v-for="p in programs" :key="p.id" class="card"><span class="badge" :class="p.access_type==='free'?'badge-free':'badge-premium'">{{p.access_type==='free'?'رایگان':'ویژه'}}</span><h2>{{p.title}}</h2><p>{{p.summary}}</p><p>{{fa(p.logs.length)}} روز انجام‌شده از {{fa(p.day_count)}}</p><progress :value="p.logs.length" :max="p.day_count"/><NuxtLink v-if="!p.access.allowed" to="/premium" class="btn btn-gold">مشاهدهٔ دسترسی ویژه</NuxtLink><button v-else class="btn btn-primary" @click="selected=selected===p.id?null:p.id">{{selected===p.id?'بستن برنامه':'مشاهدهٔ روزهای برنامه'}}</button><template v-if="selected===p.id&&p.access.allowed"><div class="day-grid section"><button v-for="d in p.days" :key="d.id" class="chip" :class="{'is-active':p.logs.some(l=>l.day_number===d.day_number)}" @click="day=d.id">{{fa(d.day_number)}}{{p.logs.some(l=>l.day_number===d.day_number)?' ✓':''}}</button></div><template v-for="d in p.days" :key="d.id"><section v-if="day===d.id"><h3>{{d.title}}</h3><p class="prose">{{d.instructions}}</p><p>{{d.reflection}}</p><div class="card-flat card"><h4>برای دفترت</h4><p>{{d.journal_prompt}}</p><NuxtLink to="/journal">نوشتن در ژورنال ←</NuxtLink></div><button class="btn btn-primary filters" :disabled="busy||p.logs.some(l=>l.day_number===d.day_number)" @click="done(p,d)">{{p.logs.some(l=>l.day_number===d.day_number)?'تمرین ثبت شده':'تمرین امروز انجام شد'}}</button></section></template></template></article></div></main></template>
